struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;

    void serialise(auto& stream) {
        // Write packet_id
        stream << packet_id;

        // Write username with length prefix
        stream << hexi::prefixed(username);

        // Write scores count first, then the scores vector
        uint32_t scores_count = static_cast<uint32_t>(scores.size());
        stream << scores_count;
        stream << scores;

        // Write null-terminated metadata
        stream << hexi::null_terminated(metadata);
    }
};

std::vector<uint8_t> serialize_packet(const NetworkPacket& packet) {
    // Create a buffer to hold the serialized data
    std::vector<uint8_t> buffer;

    // Create a buffer adaptor with the buffer
    hexi::pmc::buffer_adaptor adaptor(buffer, hexi::init_empty);

    // Create a binary stream with the adaptor
    hexi::pmc::binary_stream stream(adaptor);

    // Serialize the packet using the stream's serialise method
    stream.serialise(packet);

    // Return the buffer containing the serialized data
    return buffer;
}
```

