```cpp
#include <hexi/hexi.h>
#include <vector>
#include <cstdint>

std::vector<uint8_t> read_buffer_data(const std::vector<uint8_t>& source_buffer, size_t bytes_to_read) {
    // Create a mutable copy for the adaptor (since buffer_adaptor needs non-const reference)
    std::vector<uint8_t> buffer_copy = source_buffer;

    // Create buffer adaptor for reading
    hexi::buffer_adaptor adaptor(buffer_copy);

    // Create binary stream for reading
    hexi::binary_stream stream(adaptor);

    // Prepare destination buffer
    std::vector<uint8_t> result(bytes_to_read);

    // Read the specified number of bytes
    stream.get(result.data(), bytes_to_read);

    return result;
}

void write_buffer_data(std::vector<uint8_t>& dest_buffer, const std::vector<uint8_t>& source_data) {
    // Create buffer adaptor for writing
    hexi::buffer_adaptor adaptor(dest_buffer);

    // Create binary stream for writing
    hexi::binary_stream stream(adaptor);

    // Write data from source to destination buffer
    stream.put(source_data.data(), source_data.size());
}
```

