```cpp
#include <hexi/hexi.h>
#include <cstdint>
#include <span>

struct PacketHeader {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;
};

PacketHeader read_header_with_span(const std::span<const uint8_t> buffer) {
    // Create a buffer_adaptor from the span
    hexi::buffer_adaptor adaptor(buffer);

    // Create a binary_stream from the adaptor
    hexi::binary_stream stream(adaptor);

    // Get the read pointer (demonstrates pointer method usage)
    const uint8_t* read_ptr = adaptor.read_ptr();

    // Check available data (demonstrates buffer_adaptor method)
    constexpr std::size_t header_size = sizeof(uint32_t) + sizeof(uint16_t) + sizeof(uint16_t);
    if (adaptor.size() < header_size) {
        throw hexi::buffer_exhausted("Insufficient data for packet header");
    }

    // Get a zero-copy view of the header data (demonstrates zero-copy operation)
    // This creates a span view without copying the data
    std::span<const uint8_t> header_view = buffer.subspan(0, header_size);

    // Read the header fields using binary_stream
    PacketHeader header;

    // Read magic number (uint32_t)
    header.magic = stream.read<uint32_t>();

    // Read version (uint16_t)
    header.version = stream.read<uint16_t>();

    // Read flags (uint16_t)
    header.flags = stream.read<uint16_t>();

    return header;
}
```

