output.text:
Looking at the code fragments, I can see that `block_allocator` uses a free list structure with `free_block` nodes. The allocator manages memory blocks internally using `push()` and `pop()` operations. Let me implement a complete demonstration:

```cpp
#include <hexi/allocators/block_allocator.h>
#include <cstdint>
#include <iostream>
#include <vector>

// Note: push() and pop() are private, but we can observe their behavior
// through allocate() and deallocate() operations
template<size_t element_count = 10>
void demonstrate_block_allocator_behavior() {
    // Create a block_allocator for uint64_t with element_count blocks
    hexi::block_allocator<std::uint64_t, element_count> allocator;

    std::cout << "=== Demonstrating Block Allocator Free List Behavior ===" << std::endl;
    std::cout << "Block allocator created with " << element_count << " blocks\n" << std::endl;

    // Initially, all blocks are in the free list
    std::cout << "Phase 1: Allocating blocks (internally calls pop() on free list)" << std::endl;
    std::vector<std::uint64_t*> allocated_blocks;

    // Allocate several blocks - each allocate() internally calls pop()
    for (size_t i = 0; i < element_count / 2; ++i) {
        auto* block = allocator.allocate();
        *block = i * 100; // Write some data
        allocated_blocks.push_back(block);
        std::cout << "  Allocated block " << i << " at address: " << block 
                  << " (value: " << *block << ")" << std::endl;
    }

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nDebug info - Active allocations: " 
              << allocator.storage_active_count << std::endl;
#endif

    // Deallocate some blocks - each deallocate() internally calls push()
    std::cout << "\nPhase 2: Deallocating blocks (internally calls push() to free list)" << std::endl;
    for (size_t i = 0; i < 3 && !allocated_blocks.empty(); ++i) {
        auto* block = allocated_blocks.back();
        std::cout << "  Deallocating block at address: " << block << std::endl;
        allocator.deallocate(block);
        allocated_blocks.pop_back();
    }

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nDebug info - Active allocations: " 
              << allocator.storage_active_count << std::endl;
#endif

    // Allocate again - will reuse blocks from free list (pop() returns most recently freed)
    std::cout << "\nPhase 3: Re-allocating blocks (reuses freed blocks via pop())" << std::endl;
    for (size_t i = 0; i < 3; ++i) {
        auto* block = allocator.allocate();
        *block = i * 200;
        allocated_blocks.push_back(block);
        std::cout << "  Re-allocated block " << i << " at address: " << block 
                  << " (value: " << *block << ")" << std::endl;
    }

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nDebug info - Active allocations: " 
              << allocator.storage_active_count << std::endl;
    std::cout << "Total allocations: " << allocator.total_allocs << std::endl;
    std::cout << "Total deallocations: " << allocator.total_deallocs << std::endl;
#endif

    // Clean up remaining allocations
    std::cout << "\nPhase 4: Cleaning up remaining blocks" << std::endl;
    for (auto* block : allocated_blocks) {
        allocator.deallocate(block);
    }

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nFinal debug info:" << std::endl;
    std::cout << "  Active allocations: " << allocator.storage_active_count << std::endl;
    std::cout << "  Total allocations: " << allocator.total_allocs << std::endl;
    std::cout << "  Total deallocations: " << allocator.total_deallocs << std::endl;
#endif

    std::cout << "\n=== Free List Behavior Summary ===" << std::endl;
    std::cout << "- allocate() internally calls pop() to remove a block from free list head" << std::endl;
    std::cout << "- deallocate() internally calls push() to add a block to free list head" << std::endl;
    std::cout << "- Free list operates as a LIFO (Last-In-First-Out) stack" << std::endl;
    std::cout << "- Most recently freed blocks are reused first" << std::endl;
}

int main() {
    demonstrate_block_allocator_behavior<10>();
    return 0;
}
```

This implementation demonstrates:

1. **Free list initialization**: All blocks start in the free list
2. **pop() behavior**: `allocate()` removes blocks from the free list head
3. **push() behavior**: `deallocate()` adds blocks back to the free list head
4. **LIFO ordering**: The free list operates as a stack (most recently freed blocks are reused first)
5. **Debug tracking**: Shows allocation counts when `HEXI_DEBUG_ALLOCATORS` is defined

The free list is managed internally as a linked list where each `free_block` contains a `next` pointer, forming a singly-linked list with operations at the head for O(1) performance.

