        auto* block = allocator.allocate();
        *block = i * 200;
        allocated_blocks.push_back(block);
        std::cout << "  Re-allocated block " << i << " at address: " << block 
                  << " (value: " << *block << ")" << std::endl;
    }

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nDebug info - Active allocations: " 
              << allocator.storage_active_count << std::endl;
    std::cout << "Total allocations: " << allocator.total_allocs << std::endl;
    std::cout << "Total deallocations: " << allocator.total_deallocs << std::endl;
#endif

    // Clean up remaining allocations
    std::cout << "\nPhase 4: Cleaning up remaining blocks" << std::endl;
    for (auto* block : allocated_blocks) {
        allocator.deallocate(block);
    }

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nFinal debug info:" << std::endl;
    std::cout << "  Active allocations: " << allocator.storage_active_count << std::endl;
    std::cout << "  Total allocations: " << allocator.total_allocs << std::endl;
    std::cout << "  Total deallocations: " << allocator.total_deallocs << std::endl;
#endif

    std::cout << "\n=== Free List Behavior Summary ===" << std::endl;
    std::cout << "- allocate() internally calls pop() to remove a block from free list head" << std::endl;
    std::cout << "- deallocate() internally calls push() to add a block to free list head" << std::endl;
    std::cout << "- Free list operates as a LIFO (Last-In-First-Out) stack" << std::endl;
    std::cout << "- Most recently freed blocks are reused first" << std::endl;
}

int main() {
    demonstrate_block_allocator_behavior<10>();
    return 0;
}

