    uint32_t value = 0x78563412; // Assume big endian

    auto result = convert_with_enum<hexi::endian::conversion::big_to_native>(value);
    auto back = convert_with_enum<hexi::endian::conversion::native_to_big>(result);

    EXPECT_EQ(value, back);
