Based on the code fragments provided, I can see that `hexi::file_buffer` is a class that wraps file I/O operations. Here's the complete implementation:

```cpp
#include <hexi/file_buffer.h>
#include <vector>
#include <cstdint>
#include <filesystem>

std::vector<uint8_t> read_file_data(const std::filesystem::path& file_path, size_t bytes_to_read) {
    // Open file for reading
    hexi::file_buffer buffer(file_path);

    // Check if file opened successfully
    if (!buffer) {
        return {};
    }

    // Create destination buffer
    std::vector<uint8_t> data(bytes_to_read);

    // Read data from file
    buffer.read(data.data(), bytes_to_read);

    // Check if read was successful
    if (!buffer) {
        return {};
    }

    return data;
}

std::vector<uint8_t> preview_file_data(const std::filesystem::path& file_path, size_t bytes_to_preview) {
    // Open file for reading
    hexi::file_buffer buffer(file_path);

    // Check if file opened successfully
    if (!buffer) {
        return {};
    }

    // Create destination buffer
    std::vector<uint8_t> data(bytes_to_preview);

    // Preview data without advancing read pointer
    buffer.preview(data.data(), bytes_to_preview);

    // Check if preview was successful
    if (!buffer) {
        return {};
    }

    return data;
}

void write_file_data(const std::filesystem::path& file_path, const std::vector<uint8_t>& data) {
    // Open file for writing
    hexi::file_buffer buffer(file_path, hexi::file_mode::write);

    // Check if file opened successfully
    if (!buffer) {
        return;
    }

    // Write data to file
    buffer.write(data.data(), data.size());

    // Flush to ensure data is written
    buffer.flush();
}

size_t get_file_size(const std::filesystem::path& file_path) {
    // Open file for reading
    hexi::file_buffer buffer(file_path);

    // Check if file opened successfully
    if (!buffer) {
        return 0;
    }

    // Get the size of readable data
    return buffer.size();
}
```

