#include <gtest/gtest.h>
#include <hexi/pmc/binary_stream_writer.h>
#include <hexi/pmc/binary_stream_reader.h>
#include <hexi/pmc/buffer_adaptor.h>
#include <vector>
#include <cstdint>
#include <string>

// Include the implementation
#include "implementation.hpp"

TEST(PMCBinaryStream, SerialiseDeserialise) {
    std::vector<std::byte> buffer(1000);
    hexi::pmc::buffer_adaptor adaptor(buffer, hexi::init_empty);

    hexi::pmc::buffer& buf_ref = adaptor;
    hexi::pmc::binary_stream_writer writer(static_cast<hexi::pmc::buffer_write&>(buf_ref));
    hexi::pmc::binary_stream_reader reader(static_cast<hexi::pmc::buffer_read&>(buf_ref));

    UserData original;
    original.user_id = 12345;
    original.name = "testuser";

    serialize_object(writer, original);

    UserData deserialized;
    deserialize_object(reader, deserialized);

    EXPECT_EQ(original.user_id, deserialized.user_id);
    EXPECT_EQ(original.name, deserialized.name);
}

TEST(PMCBinaryStream, SerialiseDeserialiseMultiple) {
    std::vector<std::byte> buffer(1000);
    hexi::pmc::buffer_adaptor adaptor(buffer, hexi::init_empty);

    hexi::pmc::buffer& buf_ref = adaptor;
    hexi::pmc::binary_stream_writer writer(static_cast<hexi::pmc::buffer_write&>(buf_ref));
    hexi::pmc::binary_stream_reader reader(static_cast<hexi::pmc::buffer_read&>(buf_ref));

    UserData data1, data2;
    data1.user_id = 100;
    data1.name = "user1";
    data2.user_id = 200;
    data2.name = "user2";

    serialize_object(writer, data1);
    serialize_object(writer, data2);

    UserData result1, result2;
    deserialize_object(reader, result1);
    deserialize_object(reader, result2);

    EXPECT_EQ(data1.user_id, result1.user_id);
    EXPECT_EQ(data1.name, result1.name);
    EXPECT_EQ(data2.user_id, result2.user_id);
    EXPECT_EQ(data2.name, result2.name);
}

