};

std::vector<uint8_t> serialize_with_padding(const PaddedData& packet) {
    // TODO: implement serialization with 16-byte padding using fill<16>(0x00)
    // Write header, data (with prefix), 16 bytes of padding (0x00), then footer

    std::vector<uint8_t> buffer;
    hexi::dynamic_buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    // Write header
    stream << packet.header;

    // Write data with length prefix
    stream << hexi::prefixed(packet.data);

    // Write 16 bytes of padding filled with 0x00
    stream.fill<16>(0x00);

    // Write footer
    stream << packet.footer;

    return buffer;
}

