struct MeasurementData {
    uint32_t sensor_id;
    std::vector<float> temperatures;
    double pressure;

    void serialise(auto& adaptor) const {
        // Write sensor_id directly
        adaptor.write(sensor_id);

        // Write the number of temperature values
        uint32_t temp_count = static_cast<uint32_t>(temperatures.size());
        adaptor.write(temp_count);

        // Convert each temperature from native to little-endian and write
        for (const auto& temp : temperatures) {
            float converted_temp = hexi::endian::conditional_reverse(
                temp, 
                std::endian::native, 
                std::endian::little
            );
            adaptor.write(converted_temp);
        }

        // Convert pressure from native to little-endian and write
        double converted_pressure = hexi::endian::conditional_reverse(
            pressure, 
            std::endian::native, 
            std::endian::little
        );
        adaptor.write(converted_pressure);
    }

    void serialise(auto& adaptor) {
        // Read sensor_id directly
        adaptor.read(sensor_id);

        // Read the number of temperature values
        uint32_t temp_count;
        adaptor.read(temp_count);

        // Resize the temperatures vector
        temperatures.resize(temp_count);

        // Read each temperature and convert from little-endian to native in-place
        for (auto& temp : temperatures) {
            adaptor.read(temp);
            hexi::endian::little_to_native_inplace(temp);
        }

        // Read pressure and convert from little-endian to native in-place
        adaptor.read(pressure);
        hexi::endian::little_to_native_inplace(pressure);
    }
};

